package org.local.donusturucu.qa;
import android.os.Bundle;import android.content.Context;import android.os.ParcelFileDescriptor;import android.graphics.*;import android.graphics.pdf.PdfRenderer;import java.io.*;import java.lang.reflect.*;import java.util.*;import org.json.*;
public class BlankPages extends RichChains {
 public void onStart(){Bundle result=new Bundle();try{Context c=getTargetContext();ClassLoader loader=c.getClassLoader();Class<?>type=Class.forName("org.local.donusturucu.RichDocument",true,loader),host=Class.forName("org.local.donusturucu.RichDocument$Host",true,loader);Method read=type.getDeclaredMethod("read",File.class,String.class,host),write=type.getDeclaredMethod("write",String.class,File.class,host);read.setAccessible(true);write.setAccessible(true);Object callback=Proxy.newProxyInstance(loader,new Class<?>[]{host},new InvocationHandler(){public Object invoke(Object p,Method m,Object[]args){return null;}});File root=new File(c.getExternalFilesDir(null),"blank-page-chains");root.mkdirs();JSONArray rows=new JSONArray();
 for(int repeat=1;repeat<=3;repeat++)for(String variant:new String[]{"blank-middle","blank-edges"})for(String mid:new String[]{"pdf","docx","odt","epub","html"}){JSONObject row=new JSONObject();row.put("intermediate",mid);row.put("variant",variant);row.put("repeat",repeat);try{File source=copy(variant+".pdf",root);String before=hash(source);Object doc=read.invoke(null,source,"pdf",callback);File first=new File(root,variant+"-"+mid+"-"+repeat+"-first");first.mkdirs();File out=(File)write.invoke(doc,mid,first,callback);if(!mid.equals("pdf")){doc=read.invoke(null,out,mid,callback);File second=new File(root,variant+"-"+mid+"-"+repeat+"-final");second.mkdirs();out=(File)write.invoke(doc,"pdf",second,callback);}row.put("output",out.toString());ParcelFileDescriptor fd=ParcelFileDescriptor.open(out,ParcelFileDescriptor.MODE_READ_ONLY);PdfRenderer pdf=new PdfRenderer(fd);try{row.put("pages",pdf.getPageCount());if(pdf.getPageCount()!=3)throw new IOException("Expected3 separate pages; got"+pdf.getPageCount());for(int n=0;n<3;n++){PdfRenderer.Page page=pdf.openPage(n);Bitmap bmp=Bitmap.createBitmap(page.getWidth(),page.getHeight(),Bitmap.Config.ARGB_8888);try{bmp.eraseColor(Color.WHITE);page.render(bmp,null,null,PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);int color=bmp.getPixel(300,150);boolean white=variant.equals("blank-middle")?n==1:n!=1;boolean red=variant.equals("blank-middle")?n==0:n==1;if(white?(Color.red(color)<245||Color.green(color)<245||Color.blue(color)<245):red?(Color.red(color)<200||Color.blue(color)>30):(Color.blue(color)<200||Color.red(color)>30))throw new IOException("Wrong blank/page color/order");}finally{bmp.recycle();page.close();}}}finally{pdf.close();}if(!before.equals(hash(source)))throw new IOException("Original changed");row.put("source_unchanged",true);row.put("page_colors_and_order",true);row.put("pass",true);
 }catch(Throwable e){row.put("pass",false);row.put("error",e.toString());if(e instanceof InvocationTargetException)row.put("cause",((InvocationTargetException)e).getCause().toString());}rows.put(row);JSONObject report=new JSONObject();report.put("cases",rows.length());int failures=0;for(int i=0;i<rows.length();i++)if(!rows.getJSONObject(i).getBoolean("pass"))failures++;report.put("failures",failures);report.put("rows",rows);Writer w=new OutputStreamWriter(new FileOutputStream(new File(root,"report.json")),"UTF-8");try{w.write(report.toString(2));}finally{w.close();}}
 result.putString("report",new File(root,"report.json").toString());finish(0,result);
 }catch(Throwable e){result.putString("error",e.toString());finish(1,result);}}
}
